package com.ias.finance;

import com.ias.trust.Problem;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ias.finance.JdbcFeeGroups.*;

class PartCoverageV2Test {
 @Test void goldenVector(){var owner=new FeeGroup.Identity(1,2,UUID.fromString("00000000-0000-0000-0000-000000000001"));var line=UUID.fromString("00000000-0000-0000-0000-000000000002");var ticket=UUID.fromString("00000000-0000-0000-0000-000000000003");var round=UUID.fromString("00000000-0000-0000-0000-000000000004");var quote=UUID.fromString("00000000-0000-0000-0000-000000000005");var op=UUID.fromString("00000000-0000-0000-0000-000000000006");var approval=UUID.fromString("00000000-0000-0000-0000-000000000007");var command=new FeeGroup.Submit(op,quote,0,Set.of(),List.of(new FeeGroup.PlanLine(line,ticket,round,1000,false)),new FeeGroup.PublishedRule("v1",200));var details=new QuoteDetails(true,"test",Map.of(line,"PART"),Map.of(line,new PartBinding(approval,1,2,3,4,"EA","FULL_LINE_SINGLE_USE_V1")));assertEquals("4184f15b6911420882e4fb14ace1632fca3c11bed748de337e8d69ff826f05c2",quoteDigest(owner,command,details));assertEquals("fcdc9f05641cf71178c8bf3eeec685b8804c59a083d592e68c041e183f925f04",JdbcMoneyLedger.digest(List.of(coverageLine(command.additions().getFirst(),details))));}
 @Test void legacyDigestRemainsStableAndV2BindsEveryAuthorityField(){
  var owner=new FeeGroup.Identity(1,2,UUID.randomUUID());var line=UUID.randomUUID();var command=new FeeGroup.Submit(UUID.randomUUID(),UUID.randomUUID(),0,Set.of(),List.of(new FeeGroup.PlanLine(line,UUID.randomUUID(),UUID.randomUUID(),1000,false)),new FeeGroup.PublishedRule("v1",200));
  var legacy=new QuoteDetails(true,"test",Map.of(line,"PART"));var legacyRoundTrip=FinanceController.JSON.readValue("{\"chargesCustomer\":true,\"pricingDescription\":\"test\",\"kinds\":{\""+line+"\":\"PART\"}}",QuoteDetails.class);
  assertEquals(quoteDigest(owner,command,legacy),quoteDigest(owner,command,legacyRoundTrip));
  var id=UUID.randomUUID();var part=new PartBinding(id,1,2,3,4,"EA","FULL_LINE_SINGLE_USE_V1");var details=new QuoteDetails(true,"test",Map.of(line,"PART"),Map.of(line,part));String digest=quoteDigest(owner,command,details);assertNotEquals(quoteDigest(owner,command,legacy),digest);
  for(var changed:List.of(new PartBinding(UUID.randomUUID(),1,2,3,4,"EA","FULL_LINE_SINGLE_USE_V1"),new PartBinding(id,2,2,3,4,"EA","FULL_LINE_SINGLE_USE_V1"),new PartBinding(id,1,5,3,4,"EA","FULL_LINE_SINGLE_USE_V1"),new PartBinding(id,1,2,5,4,"EA","FULL_LINE_SINGLE_USE_V1"),new PartBinding(id,1,2,3,5,"EA","FULL_LINE_SINGLE_USE_V1"),new PartBinding(id,1,2,3,4,"BOX","FULL_LINE_SINGLE_USE_V1")))assertNotEquals(digest,quoteDigest(owner,command,new QuoteDetails(true,"test",Map.of(line,"PART"),Map.of(line,changed))));
  var row=coverageLine(command.additions().getFirst(),details);assertEquals(part.canonical(),row.get("partBinding"));
 }
 @Test void unverifiedCustomerPaidPartsFailClosed(){var line=UUID.randomUUID();var old=new QuoteDetails(true,"test",Map.of(line,"PART"));assertEquals(503,assertThrows(Problem.class,()->TrustedFinanceAccess.requirePartOwner(old)).status);var part=new PartBinding(UUID.randomUUID(),1,2,3,1,"EA","FULL_LINE_SINGLE_USE_V1");var versioned=new QuoteDetails(true,"test",Map.of(line,"PART"),Map.of(line,part));assertEquals(503,assertThrows(Problem.class,()->TrustedFinanceAccess.requirePartOwner(versioned)).status);assertDoesNotThrow(()->TrustedFinanceAccess.requirePartOwner(new QuoteDetails(true,"test",Map.of(line,"LABOR"))));}
 @Test void malformedOrAmbiguousBindingsCannotBeCreated(){var id=UUID.randomUUID();assertThrows(IllegalArgumentException.class,()->new PartBinding(id,1,2,3,0,"EA","FULL_LINE_SINGLE_USE_V1"));assertThrows(IllegalArgumentException.class,()->new PartBinding(id,1,2,3,1,"EA","INFERRED"));var binding=new PartBinding(id,1,2,3,1,"EA","FULL_LINE_SINGLE_USE_V1");var a=UUID.randomUUID();var b=UUID.randomUUID();assertThrows(IllegalArgumentException.class,()->new QuoteDetails(true,"test",Map.of(a,"PART",b,"PART"),Map.of(a,binding,b,binding)));assertThrows(IllegalArgumentException.class,()->new QuoteDetails(true,"test",Map.of(a,"LABOR"),Map.of(a,binding)));}
 @Test void unitUsesExactCatalogText(){var id=UUID.randomUUID();assertEquals("件",new PartBinding(id,1,2,3,1,"件","FULL_LINE_SINGLE_USE_V1").unitCode());assertEquals("EA-1",new PartBinding(id,1,2,3,1,"EA-1","FULL_LINE_SINGLE_USE_V1").unitCode());assertThrows(IllegalArgumentException.class,()->new PartBinding(id,1,2,3,1," 件 ","FULL_LINE_SINGLE_USE_V1"));assertThrows(IllegalArgumentException.class,()->new PartBinding(id,1,2,3,1,"件\n", "FULL_LINE_SINGLE_USE_V1"));}
}
